sys_script_client.script:
// MSSCUSTODY-5334 - Created this script to show fields on change of Bulk Field Group selection 
function onChange(control, oldValue, newValue, isLoading, isTemplate) {

    if ((isLoading || newValue === '') && (((g_form.getValue('outcome')) == 'Amend Trade') || (g_form.getValue('outcome') == 'Amend and CONF'))) { // Added outcome condition as fix for MSSCUSTODY-6643
        //

        var bulkFieldGroup = g_form.getValue('bulk_field_group');
        var bulkTaskType = g_scratchpad.blkTskRelated;
        var taskState = g_form.getValue('state').toString();
        // MSSCUSTODY 5981
        if (bulkFieldGroup && (bulkTaskType.indexOf('Checker') > -1 || bulkTaskType.indexOf('Handler') > -1)) { // MSSCUSTODY 6780 - Make fields read only for checker and handler

            g_form.setDisplay('bulk_field_group', true);
            var fieldstoMakeReadOnlyOnLoad = ['amend_trade_date',
                'settlement_date',
                'bulk_field_group',
                'amend_settlement_amount',
                'customer_reference',
                'security_id_sec_id',
                'amend_security_id_sec_id_ref',
                'amend_location_code',
                'amend_gdi_indicator',
                'amend_hmi_indicator',
                'amend_script_hold_indicator',
                'amend_cash_hold_indicator',
                'counterparty_reference',
                'amend_payment_method',
                'amend_counterparty_code',
                'amend_counterparty_code_ref',
                'amend_counterparty_settlement_account_number',
                'amend_a_c_of_client',
                'amend_deliverer_custodian_bic_receiver_custodian_bic',
                'amend_seller_bic_buyer_bic',
                'amend_receiver_custodian_bic', // MSSCUSTODY-7159 - Added Receiver Custodian (BIC)
                'amend_buyer_bic', // MSSCUSTODY-7159 - Added Buyer (BIC)
                'amend_place_of_settlement_bic',
                'amend_charges_type',
                'amend_charges_ccy',
                'amend_charges_amt',
                'amend_swh', // MSSCuSTODY-7898 - Added SWH
                'amend_iss',
                'amend_fa'
            ];
            fieldstoMakeReadOnlyOnLoad.forEach(function(field) {
                g_form.setReadOnly(field, true);
            });


        } else {
            g_form.setMandatory('bulk_field_group', false);
            g_form.setDisplay('bulk_field_group', false);
        }

        /*
        Eligibility Check Artifacts: 
        Script Include : x_hsb11_mss_c_proc.MSSCustodyAmendUtils - evalAmendEligibility
        System Property: x_hsb11_mss_c_proc.enableautomatedamend.market - Only available markets will allow this script to execute
        System Property: x_hsb11_mss_c_proc.enableautomatedamend.outcomes - Only available markets will allow this script to execute
        */
        var eligbleCheck = new GlideAjax('x_hsb11_mss_c_proc.MSSCustodyAmendUtils');
        eligbleCheck.addParam('sysparm_name', 'evalAmendEligibility');
        eligbleCheck.addParam('sysparm_recOutcome', g_form.getValue('outcome'));
        eligbleCheck.addParam('sysparm_recSysID', g_form.getUniqueValue());
        eligbleCheck.addParam('sysparm_tableName', 'x_hsb11_hsbc_mss_o_hsbc_bulk_transaction');
        eligbleCheck.getXMLAnswer(handleEligiblity);

        function handleEligiblity(check) {

            if (check.toString() == 'true') {
                if ((parseInt(g_scratchpad.active_trades) > 1) || g_scratchpad.bulkMakerTaskCount > 0) {
                    g_form.setDisplay('bulk_field_group', true);
                    g_form.setMandatory('bulk_field_group', true);
                } else {
                    g_form.setMandatory('bulk_field_group', false);
                    g_form.setDisplay('bulk_field_group', false);
                }
                var field_group = [];
                var bulk_field = g_form.getValue('bulk_field_group');
                if (bulk_field == 'customer_reference') {
                    field_group = ['customer_reference'];
                } else if (bulk_field == 'trade_settl_date') {
                    field_group = ['amend_trade_date', 'settlement_date', 'amend_swh']; // MSSCUSTODY-7898 - Added SWH field
                } else if (bulk_field == 'cash_hold_indicator') {
                    field_group = ['amend_cash_hold_indicator'];
                } else if (bulk_field == 'beneficiary_details') {
                    field_group = ['amend_a_c_of_client', 'amend_deliverer_custodian_bic_receiver_custodian_bic', 'amend_seller_bic_buyer_bic', 'amend_place_of_settlement_bic', 'amend_buyer_bic', 'amend_receiver_custodian_bic']; // // MSSCUSTODY-7159 - Added Buyer BIC and Receiver Custodian BIC field
                } else if (bulk_field == 'counterparty_details') {
                    field_group = ['counterparty_reference', 'amend_payment_method', 'amend_counterparty_code', 'amend_counterparty_settlement_account_number', 'amend_counterparty_code_ref']; // MSSCUSTODY 5862 - Added remote table fields
                } else if (bulk_field == 'location_gdi') {
                    field_group = ['amend_location_code', 'amend_gdi_indicator'];
                } else if (bulk_field == 'hmi_indicator​') {
                    field_group = ['amend_hmi_indicator'];
                } else if (bulk_field == 'script_hold_indicator') {
                    field_group = ['amend_script_hold_indicator'];
                } else if (bulk_field == 'security_id') {
                    field_group = ['security_id_sec_id', 'amend_security_id_sec_id_ref']; // MSSCUSTODY 5862 - Added remote table fields
                } else if (bulk_field == 'amendment_charges') {
                    field_group = ['amend_charges_ccy', 'amend_charges_amt', 'amend_charges_type'];
                } else if (bulk_field == 'blank_trade_date') {
                    field_group = [];
                } else if (bulk_field == 'fa') {
                    field_group = ['amend_fa'];
                } else if (bulk_field == 'iss') {
                    field_group = ['amend_iss'];
                }

                var fieldsToHide = [
                    'amend_settlement_currency',
                    'amend_deal_price',
                    'amend_settlement_amount',
                    'settlement_date',
                    'amend_trade_date',
                    'amend_location_code',
                    'security_id_sec_id',
                    'counterparty_reference',
                    'customer_reference',
                    'amend_payment_method',
                    'amend_switch_indicator',
                    'amend_switch_account',
                    'amend_suspense_account_number',
                    'amend_counterparty_settlement_account_number',
                    'amend_convert_to_account_switching',
                    'amend_a_c_of_client',
                    'amend_deliverer_custodian_bic_receiver_custodian_bic',
                    'amend_seller_bic_buyer_bic',
                    'amend_receiver_custodian_bic', // MSSCUSTODY-7159 - Added Receiver Custodian (BIC)
                    'amend_buyer_bic', // MSSCUSTODY-7159 - Added Buyer (BIC)
                    'amend_place_of_settlement_bic',
                    'amend_gdi_indicator',
                    'amend_counterparty_code',
                    'amend_hmi_indicator',
                    'amend_cash_hold_indicator',
                    'amend_script_hold_indicator',
                    'amend_deal_currency',
                    'amend_charges_ccy',
                    'amend_charges_amt',
                    'amend_charges_type',
                    'amend_security_id_sec_id_ref',
                    'amend_switch_account_ref',
                    'amend_counterparty_code_ref',
                    'amend_nssc',
                    'amend_swh', // MSSCuSTODY-7898 - Added SWH
                    'amend_fa',
                    'amend_iss',
                    'amend_switch_reference'
                ];


                if ((parseInt(g_form.getValue('active_trade_count')) > 1) || g_scratchpad.bulkMakerTaskCount > 0) {
                    // Setting display of above fields as false on loading of bulk form.
                    fieldsToHide.forEach(function(field) {
                        g_form.setDisplay(field, false);
                    });

                    field_group.forEach(function(field) {
                        g_form.setDisplay(field, true);
                        // MSSCUSTODY 5985 - Enable/disable fields as per configuration matrix
                        var bulkID = g_form.getUniqueValue(); // Get the current record's sys_id
                        var glideAjax = new GlideAjax('x_hsb11_hsbc_mss_o.MSSAmendUtilsCore');
                        glideAjax.addParam('sysparm_name', 'fetchEligibleFieldsForBulkAmend');
                        glideAjax.addParam('sysparm_bulkid', bulkID); // Pass bulk ID as a parameter

                        glideAjax.getXMLAnswer(function(response) {
                            var result = JSON.parse(response); // Parse the JSON response
                            var hiddenFields = result.hiddenFields;
                            var nonEditableFields = result.nonEditableFields;

                            // Hide the fields
                            hiddenFields.forEach(function(field) {
                                if (g_form.getControl(field)) { // Check if the field exists on the form
                                    g_form.setDisplay(field, false); // Hide the field
                                }
                            });

                            // Make fields non-editable

                            nonEditableFields.forEach(function(field) {
                                if (g_form.getControl(field)) { // Check if the field exists on the form
                                    g_form.setReadOnly(field, true); // Make the field read-only
                                }
                            });
                        });


                    });
                }

                var fieldsToShowForSingleAmend = [
                    'amend_settlement_currency',
                    'amend_deal_price',
                    'amend_settlement_amount',
                    'settlement_date',
                    'amend_trade_date',
                    'amend_location_code',
                    'security_id_sec_id',
                    'counterparty_reference',
                    'customer_reference',
                    'amend_payment_method',
                    'amend_switch_indicator',
                    'amend_switch_account',
                    'amend_suspense_account_number',
                    'amend_counterparty_settlement_account_number',
                    'amend_convert_to_account_switching',
                    'amend_a_c_of_client',
                    'amend_deliverer_custodian_bic_receiver_custodian_bic',
                    'amend_seller_bic_buyer_bic',
                    'amend_receiver_custodian_bic', // MSSCUSTODY-7159 - Added Receiver Custodian (BIC)
                    'amend_buyer_bic', // MSSCUSTODY-7159 - Added Buyer (BIC)
                    'amend_place_of_settlement_bic',
                    'amend_gdi_indicator',
                    'amend_counterparty_code',
                    'amend_hmi_indicator',
                    'amend_cash_hold_indicator',
                    'amend_script_hold_indicator',
                    'amend_deal_currency',
                    'amend_charges_ccy',
                    'amend_charges_amt',
                    'amend_charges_type',
                    'amend_security_id_sec_id_ref',
                    'amend_switch_account_ref',
                    'amend_counterparty_code_ref',
                    'amend_nssc',
                    'amend_iss', // ISS 7761
                    'amend_swh', // MSSCuSTODY-7898 - Added SWH
                    'amend_fa',
                    'amend_switch_reference'


                ];

                if ((parseInt(g_form.getValue('active_trade_count')) == 1) && (g_scratchpad.bulkMakerTaskCount == 1)) { // MSSCUSTODY-7039

                    // Setting display of above fields as false on loading of bulk form.

                    fieldsToShowForSingleAmend.forEach(function(field) {
                        g_form.setDisplay(field, true);
                    });
                }
            } else {
                g_form.setMandatory('bulk_field_group', false);
                g_form.setDisplay('bulk_field_group', false);
                g_form.setDisplay('amend_settlement_currency', false);
                g_form.setDisplay('amend_deal_price', false);
                g_form.setDisplay('customer_reference', false);
                g_form.setDisplay('amend_deal_price', false);
                g_form.setDisplay('amend_settlement_amount', false);
                g_form.setDisplay('settlement_date', false);
                g_form.setDisplay('amend_trade_date', false);
                g_form.setDisplay('amend_location_code', false);
                g_form.setDisplay('security_id_sec_id', false);
                g_form.setDisplay('counterparty_reference', false);
                g_form.setDisplay('amend_payment_method', false);
                g_form.setDisplay('amend_switch_indicator', false);
                g_form.setDisplay('amend_switch_account', false);
                g_form.setDisplay('amend_suspense_account_number', false);
                g_form.setDisplay('amend_counterparty_settlement_account_number', false);
                g_form.setDisplay('amend_a_c_of_client', false);
                g_form.setDisplay('amend_convert_to_account_switching', false);
                g_form.setDisplay('amend_deliverer_custodian_bic_receiver_custodian_bic', false);
                g_form.setDisplay('amend_seller_bic_buyer_bic', false);
                g_form.setDisplay('amend_buyer_bic', false); // MSSCUSTODY-7159
                g_form.setDisplay('amend_receiver_custodian_bic', false); // MSSCUSTODY-7159
                g_form.setDisplay('amend_gdi_indicator', false);
                g_form.setDisplay('amend_counterparty_code', false);
                g_form.setDisplay('amend_hmi_indicator', false);
                g_form.setDisplay('amend_cash_hold_indicator', false);
                g_form.setDisplay('amend_deal_currency', false);
                g_form.setDisplay('amend_place_of_settlement_bic', false);
                g_form.setDisplay('amend_script_hold_indicator', false);
                g_form.setDisplay('amend_charges_ccy', false);
                g_form.setDisplay('amend_charges_amt', false);
                g_form.setDisplay('amend_charges_type', false);
                g_form.setDisplay('amend_security_id_sec_id_ref', false);
                g_form.setDisplay('amend_switch_account_ref', false);
                g_form.setDisplay('amend_counterparty_code_ref', false);
                g_form.setDisplay('amend_nssc', false);
                g_form.setDisplay('amend_swh', false); // MSSCUSTODY-7898
                g_form.setDisplay('amend_iss', false);
                g_form.setDisplay('amend_fa', false);
                g_form.setDisplay('amend_switch_reference', false);

            }

        }
        return;
    }

    /*
    Eligibility Check Artifacts: 
    Script Include : x_hsb11_mss_c_proc.MSSCustodyAmendUtils - evalAmendEligibility
    System Property: x_hsb11_mss_c_proc.enableautomatedamend.market - Only available markets will allow this script to execute
    System Property: x_hsb11_mss_c_proc.enableautomatedamend.outcomes - Only available markets will allow this script to execute
    */

    if ((g_form.getValue('outcome') == 'Amend Trade') || (g_form.getValue('outcome') == 'Amend and CONF')) {

        var eligbleCheck = new GlideAjax('x_hsb11_mss_c_proc.MSSCustodyAmendUtils');
        eligbleCheck.addParam('sysparm_name', 'evalAmendEligibility');
        eligbleCheck.addParam('sysparm_recOutcome', g_form.getValue('outcome'));
        eligbleCheck.addParam('sysparm_recSysID', g_form.getUniqueValue());
        eligbleCheck.addParam('sysparm_tableName', 'x_hsb11_hsbc_mss_o_hsbc_bulk_transaction');
        eligbleCheck.getXMLAnswer(handleEligiblity);

        function handleEligiblity(check) {
            if (check.toString() == 'true') {
                //Type appropriate comment here, and begin script below
                var fieldsToHide = [
                    'amend_location_code',
                    'settlement_date',
                    'amend_trade_date',
                    'security_id_sec_id',
                    'counterparty_reference',
                    'customer_reference',
                    'amend_payment_method',
                    'amend_switch_indicator',
                    'amend_switch_account',
                    'amend_suspense_account_number',
                    'amend_counterparty_settlement_account_number',
                    'amend_convert_to_account_switching',
                    'amend_a_c_of_client',
                    'amend_deliverer_custodian_bic_receiver_custodian_bic',
                    'amend_seller_bic_buyer_bic',
                    'amend_receiver_custodian_bic', // MSSCUSTODY-7159 - Added Receiver Custodian (BIC)
                    'amend_buyer_bic', // MSSCUSTODY-7159 - Added Buyer (BIC)
                    'amend_place_of_settlement_bic',
                    'amend_gdi_indicator',
                    'amend_counterparty_code',
                    'amend_hmi_indicator',
                    'amend_cash_hold_indicator',
                    'amend_script_hold_indicator',
                    'amend_charges_ccy',
                    'amend_charges_amt',
                    'amend_charges_type',
                    'amend_security_id_sec_id_ref',
                    'amend_switch_account_ref',
                    'amend_counterparty_code_ref',
                    'amend_nssc',
                    'amend_swh', // MSSCuSTODY-7898 - Added SWH
                    'amend_iss',
                    'amend_fa',
                    'amend_switch_reference'

                ];
                // Setting display of above fields as false on change of bulk field group.
                fieldsToHide.forEach(function(field) {
                    g_form.setDisplay(field, false);
                    //g_form.clearValue(field);
                });
                //alert(g_form.getValue('bulk_field_group'));


                var ownBusiness = g_scratchpad.ownB;
                if (g_form.getValue('bulk_field_group') == 'customer_reference') {
                    g_form.setDisplay('customer_reference', true);
                } else if (g_form.getValue('bulk_field_group') == 'trade_settl_date') {
                    //alert('trade Date loop');
                    g_form.setDisplay('amend_trade_date', true);
                    g_form.setDisplay('settlement_date', true);
                    g_form.setDisplay('amend_swh', true); // MSSCUSTODY-7898
                } else if (g_form.getValue('bulk_field_group') == 'cash_hold_indicator') {
                    g_form.setDisplay('amend_cash_hold_indicator', true);
                } else if (g_form.getValue('bulk_field_group') == 'beneficiary_details') {
                    g_form.setDisplay('amend_a_c_of_client', true);
                    g_form.setDisplay('amend_deliverer_custodian_bic_receiver_custodian_bic', true);
                    g_form.setDisplay('amend_seller_bic_buyer_bic', true);
                    g_form.setDisplay('amend_place_of_settlement_bic', true);
                    g_form.setDisplay('amend_buyer_bic', true); // MSSCUSTODY-7159
                    g_form.setDisplay('amend_receiver_custodian_bic', true); // MSSCUSTODY-7159
                } else if (g_form.getValue('bulk_field_group') == 'counterparty_details') {
                    g_form.setDisplay('counterparty_reference', true);
                    g_form.setDisplay('amend_payment_method', true);
                    g_form.setDisplay('amend_counterparty_code', true);
                    g_form.setDisplay('amend_counterparty_settlement_account_number', true);

                    // MSSCUSTODY 5862 - Added remote table field ad display field message
                    g_form.setDisplay('amend_counterparty_code_ref', true);
                    if (g_form.getValue('amend_payment_method') != 'TFR') {
                        g_form.setReadOnly('amend_counterparty_settlement_account_number', true);
                    }
                } else if (g_form.getValue('bulk_field_group') == 'location_gdi') {
                    g_form.setDisplay('amend_gdi_indicator', true);
                    g_form.setDisplay('amend_location_code', true);

                    if (ownBusiness.indexOf("SG") <= -1) {
                        g_form.removeOption('amend_gdi_indicator', 'Hold by Bypass');
                    } else {
                        g_form.addOption('amend_gdi_indicator', 'Hold by Bypass', 'Hold by Bypass');
                    }

                } else if (g_form.getValue('bulk_field_group') == 'hmi_indicator​') {
                    g_form.setDisplay('amend_hmi_indicator', true);
                } else if (g_form.getValue('bulk_field_group') == 'script_hold_indicator') {
                    g_form.setDisplay('amend_script_hold_indicator', true);
                } else if (g_form.getValue('bulk_field_group') == 'script_hold_indicator') {
                    g_form.setDisplay('amend_script_hold_indicator', true);
                } else if (g_form.getValue('bulk_field_group') == 'security_id') {
                    g_form.setDisplay('security_id_sec_id', true);

                    // MSSCUSTODY 5862 - Added remote table field and display message
                    g_form.setDisplay('amend_security_id_sec_id_ref', true);
                } else if (g_form.getValue('bulk_field_group') == 'amendment_charges') {
                    g_form.setDisplay('amend_charges_ccy', true);
                    g_form.setDisplay('amend_charges_amt', true);
                    g_form.setDisplay('amend_charges_type', true);

                    if (g_form.getValue('bulk_id.amend_charges_type') != 'U') {
                        g_form.setReadOnly('bulk_id.amend_charges_ccy', true);
                        g_form.setReadOnly('bulk_id.amend_charges_amt', true);
                        g_form.setMandatory('bulk_id.amend_charges_ccy', false);
                        g_form.setMandatory('bulk_id.amend_charges_amt', false);
                    } else if (g_form.getValue('bulk_id.amend_charges_type') == 'U') {
                        g_form.setReadOnly('bulk_id.amend_charges_ccy', false);
                        g_form.setReadOnly('bulk_id.amend_charges_amt', false);
                        g_form.setMandatory('bulk_id.amend_charges_ccy', true);
                        g_form.setMandatory('bulk_id.amend_charges_amt', true);
                    }
                } else if (g_form.getValue('bulk_field_group').trim() =='iss') {
					console.log('ISS Loop');
                    g_form.setDisplay('amend_iss', true);
                } else if (g_form.getValue('bulk_field_group').trim() == 'fa') {
					console.log('Fa Loop');
                    g_form.setDisplay('amend_fa', true);
                }
                //alert('Value Check result ' + (g_form.getValue('bulk_field_group') == "fa​") + " Value passed on = "  + g_form.getValue('bulk_field_group'));
                //alert('final');

                // MSSCUSTODY 5985 - Call the script includes function to fetch fields to hide
                var bulkID = g_form.getUniqueValue(); // Get the current record's sys_id
                var glideAjax = new GlideAjax('x_hsb11_hsbc_mss_o.MSSAmendUtilsCore');
                glideAjax.addParam('sysparm_name', 'fetchEligibleFieldsForBulkAmend');
                glideAjax.addParam('sysparm_bulkid', bulkID); // Pass bulk ID as a parameter

                glideAjax.getXMLAnswer(function(response) {
                    var result = JSON.parse(response); // Parse the JSON response
					console.log('Hidden Matrix loop ' + JSON.stringify(result));
                    var hiddenFields = result.hiddenFields;
                    var nonEditableFields = result.nonEditableFields;

                    // Hide the fields
                    hiddenFields.forEach(function(field) {
                        if (g_form.getControl(field)) { // Check if the field exists on the form
                            g_form.setDisplay(field, false); // Hide the field
                        }
                    });

                    // Make fields non-editable
                    nonEditableFields.forEach(function(field) {
                        if (g_form.getControl(field)) { // Check if the field exists on the form
                            g_form.setReadOnly(field, true); // Make the field read-only
                        }
                    });
                });


            }
        }
    }
}
